preConditionHook:
// THE 3/10 OSCILLATOR -- Grimes's fast line, in the settled form (merge
// decision 2): the difference of two SIMPLE averages of the close,
//     osc = average of close over fastLen bars, less the average
//           of close over slowLen bars
// with fastLen 3 and slowLen 10 as the book's defaults. Never the MACD word:
// Appendix B spells the construction out as plain moving averages, and the
// chapter 16 restatement in exponential terms loses to it.
// EL's Average RECOMPUTES from scratch every bar (VERIFIED: matched a fresh
// loop on 2,808/2,808 bars; it is NOT a rolling accumulator like the WFSafe_
// wrappers), and Summation adds the newest bar first and works backwards,
// with a single divide at the end -- which is how the loops below run.
// Both averages run over a PRICE expression, which has real bar history, so
// they are recomputed from the bars rather than mirrored; only osc ITSELF is
// a variable, and that is what the ring buffers below mirror.
// The whole quantity is a difference of prices, so it passes the shift test.
// Scratch is declared in localVariables, never at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a
// redefinition when the rule is placed twice in one strategy.
oscFast = 0.0;
for (int i = 0; i < (int)fastLen; ++i) {
    oscFast += close[i];
}
oscFast = oscFast / (int)fastLen;
oscSlow = 0.0;
for (int i = 0; i < (int)slowLen; ++i) {
    oscSlow += close[i];
}
oscSlow = oscSlow / (int)slowLen;
osc = oscFast - oscSlow;
// THE SLOW LINE: a signalLen-period SIMPLE average of the fast line, which in
// EasyLanguage is an Average over a VARIABLE -- so it reads osc's own
// zero-filled warm-up history and the rule guards its first signalLen bars on
// the bar counter rather than acting on a diluted average.
// osc is an EL VARIABLE, so osc[k] reads the variable's OWN history, which
// holds its initial 0 for every bar before the strategy's first evaluated
// one. Mirrored here as a zero-seeded ring buffer, re-seeded if the depth
// ever changes -- exactly what AwesomeOscillatorSlope, AtrRising and
// BarRangeAboveStd do for the same reason. The rule GUARDS its own warm-up
// on the bar counter instead of comparing against those zeros.
// Depth signalLen: the whole averaging window, lags 0..signalLen - 1. The
// mean is taken over the buffer the way BarRangeAboveStd takes its own.
if (oscHistory.size() != (std::size_t)(int)signalLen) {
    oscHistory.assign((std::size_t)(int)signalLen, 0.0);
    oscCursor = 0;
}
oscHistory[oscCursor] = osc;
oscCursor = (oscCursor + 1) % oscHistory.size();
signal = 0.0;
for (double v : oscHistory) {
    signal += v;
}
signal = signal / (int)signalLen;
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, which carries the measurements). Seeded
// with a full N-term sum on the study's first calculated bar or whenever the
// length changes, and updated thereafter as TWO statements -- EL evaluates
// S[1] + in - out left to right, and folding it to S += in - out rounds
// differently and lands on the other side of a threshold (@OJ 2015-02-20).
// The remembered length is atrSeedLen, not atrLength: atrLength is this
// rule's INPUT, the merged parameter name.
if (atrSeedLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrSeedLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLength;
band = thresholdAtr * atr;
// THE BLOCKER: true -- the trade is allowed -- unless the slow line is beyond
// the band AND has just turned back toward zero. Kept whole because
// NOT(extended AND turning) is an OR of two negations and ANDed entry panes
// cannot rebuild an OR (the SmallWeakSignalBarBlock precedent, cited for its
// shape). While sigReady is false the rule is TRUE: a blocker must not block
// on a zero-filled warm-up reading.
// signal is itself an EL variable, so signal[1] is the variable's own
// history -- mirrored as a second zero-seeded ring buffer, depth 2.
if (sigHistory.size() != (std::size_t)2) {
    sigHistory.assign((std::size_t)2, 0.0);
    sigCursor = 0;
}
sigHistory[sigCursor] = signal;
sigCursor = (sigCursor + 1) % sigHistory.size();
sigLag1 = sigHistory[(sigCursor + sigHistory.size() - 2) % sigHistory.size()];
sigReady = ctx.CurrentBar() > (int)signalLen;
